import{_ as r,o as t,c as a,a3 as l}from"./chunks/framework.BrO6lPIi.js";const d=JSON.parse('{"title":"调试工具与技巧","description":"本指南面向 AI Helper 的开发者、测试人员与高级用户，聚焦以下目标：。","frontmatter":{"title":"调试工具与技巧","description":"本指南面向 AI Helper 的开发者、测试人员与高级用户，聚焦以下目标：。"},"headers":[],"relativePath":"故障排除与常见问题/调试工具与技巧/index.md","filePath":"故障排除与常见问题/调试工具与技巧/index.md","lastUpdated":null}'),o={name:"故障排除与常见问题/调试工具与技巧/index.md"};function i(n,e,s,g,c,b){return t(),a("div",null,[...e[0]||(e[0]=[l(`<h1 id="调试工具与技巧" tabindex="-1">调试工具与技巧 <a class="header-anchor" href="#调试工具与技巧" aria-label="Permalink to &quot;调试工具与技巧&quot;">​</a></h1><details class="details custom-block"><summary>本文引用的源码文件</summary><p><strong>本文引用的文件</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/tools/debugger-tools.js" target="_blank" rel="noreferrer">src/background/tools/debugger-tools.js</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/tool-debugger.js" target="_blank" rel="noreferrer">src/background/tool-debugger.js</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/debugger/debugger-session.js" target="_blank" rel="noreferrer">src/background/debugger/debugger-session.js</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/shared/logger.js" target="_blank" rel="noreferrer">src/shared/logger.js</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/logger.js" target="_blank" rel="noreferrer">agent/src/logger.js</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/token-recorder.js" target="_blank" rel="noreferrer">src/background/token-recorder.js</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/storage/token-store.js" target="_blank" rel="noreferrer">src/storage/token-store.js</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/side_panel/token-stats-panel.js" target="_blank" rel="noreferrer">src/side_panel/token-stats-panel.js</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/side_panel/utils.js" target="_blank" rel="noreferrer">src/side_panel/utils.js</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/side_panel/panel-context.js" target="_blank" rel="noreferrer">src/side_panel/panel-context.js</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/test/unit/debugger-executor.unit.test.js" target="_blank" rel="noreferrer">test/unit/debugger-executor.unit.test.js</a></li></ul></details><h2 id="目录" tabindex="-1">目录 <a class="header-anchor" href="#目录" aria-label="Permalink to &quot;目录&quot;">​</a></h2><ol><li><a href="#引言">引言</a></li><li><a href="#项目结构与调试边界">项目结构与调试边界</a></li><li><a href="#核心调试能力总览">核心调试能力总览</a></li><li><a href="#chrome-devtools-面板使用指南">Chrome DevTools 面板使用指南</a></li><li><a href="#扩展专用调试工具">扩展专用调试工具</a></li><li><a href="#日志系统配置与使用">日志系统配置与使用</a></li><li><a href="#性能监控与-token-统计">性能监控与 Token 统计</a></li><li><a href="#网络抓包与-api-调试技巧">网络抓包与 API 调试技巧</a></li><li><a href="#常见调试场景与问题定位">常见调试场景与问题定位</a></li><li><a href="#依赖关系分析">依赖关系分析</a></li><li><a href="#故障排查清单">故障排查清单</a></li><li><a href="#结论">结论</a></li></ol><h2 id="引言" tabindex="-1">引言 <a class="header-anchor" href="#引言" aria-label="Permalink to &quot;引言&quot;">​</a></h2><p>本指南面向 AI Helper 的开发者、测试人员与高级用户，聚焦以下目标：</p><ul><li>在 Chrome 扩展端（Manifest V3）与独立 Agent 端之间建立可复现、可观测的调试路径。</li><li>说明如何正确使用内置 <code>debug_page</code> 工具完成页面级调试、网络抓包、截图与环境模拟。</li><li>说明扩展端与 Agent 端的日志体系、Token 统计面板、执行时间追踪思路。</li><li>提供 WebSocket、HTTP、响应体分析与错误过滤的实操方法。</li><li>给出 background 页面、content script、side panel 三类典型调试场景的操作步骤与排错建议。</li></ul><p>本项目为双进程架构：扩展端位于 <code>src/</code>，Agent 端入口为 <code>agent/src/server.js</code>；两端版本号保持同步，当前文档以 2.7.0 为准。Agent 源码修改后必须重启进程，新接口才生效。</p><h2 id="项目结构与调试边界" tabindex="-1">项目结构与调试边界 <a class="header-anchor" href="#项目结构与调试边界" aria-label="Permalink to &quot;项目结构与调试边界&quot;">​</a></h2><p>AI Helper 的调试边界由三层组成：</p><ul><li><strong>Side Panel 层</strong>：对话界面、执行日志、Token 统计、工作区等 UI。</li><li><strong>Background Service Worker 层</strong>：消息路由、ReAct 执行循环、工具调度、本地 Agent 通信、调试会话管理。</li><li><strong>Agent 本地服务层</strong>：文件读写、命令执行、长期记忆、RAG、MCP 工具注册。</li></ul><pre class="mermaid">graph TB
SP[&quot;Side Panel&lt;br/&gt;侧边栏界面&quot;] --&gt; BG[&quot;Background Service Worker&lt;br/&gt;扩展核心逻辑&quot;]
BG --&gt; AGENT[&quot;本地 Agent 服务&lt;br/&gt;Node.js 进程&quot;]
BG --&gt; CDP[&quot;Chrome DevTools Protocol&lt;br/&gt;页面调试会话&quot;]
BG --&gt; IDB[&quot;IndexedDB&lt;br/&gt;Token 统计存储&quot;]
AGENT --&gt; LOGS[&quot;Agent 审计日志&lt;br/&gt;JSON Lines 文件&quot;]
BG --&gt; CONSOLE[&quot;浏览器控制台&lt;br/&gt;扩展日志输出&quot;]
</pre><p><strong>图表来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/side_panel/token-stats-panel.js#L1-L50" target="_blank" rel="noreferrer">src/side_panel/token-stats-panel.js#L1-L50</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/debugger/debugger-session.js#L1-L20" target="_blank" rel="noreferrer">src/background/debugger/debugger-session.js#L1-L20</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/storage/token-store.js#L1-L12" target="_blank" rel="noreferrer">src/storage/token-store.js#L1-L12</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/logger.js#L1-L12" target="_blank" rel="noreferrer">agent/src/logger.js#L1-L12</a></li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/debugger/debugger-session.js#L1-L20" target="_blank" rel="noreferrer">src/background/debugger/debugger-session.js#L1-L20</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/side_panel/token-stats-panel.js#L1-L50" target="_blank" rel="noreferrer">src/side_panel/token-stats-panel.js#L1-L50</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/logger.js#L1-L12" target="_blank" rel="noreferrer">agent/src/logger.js#L1-L12</a></li></ul><h2 id="核心调试能力总览" tabindex="-1">核心调试能力总览 <a class="header-anchor" href="#核心调试能力总览" aria-label="Permalink to &quot;核心调试能力总览&quot;">​</a></h2><table tabindex="0"><thead><tr><th>能力</th><th>位置</th><th>用途</th><th>关键约束</th></tr></thead><tbody><tr><td>页面调试</td><td><code>src/background/tools/debugger-tools.js</code>、<code>src/background/tool-debugger.js</code>、<code>src/background/debugger/debugger-session.js</code></td><td>attach/detach、evaluate、原生输入、截图、环境模拟</td><td>受限页面不可调试；需先 attach 再 detach；空闲自动脱离</td></tr><tr><td>网络录制</td><td><code>src/background/debugger/debugger-session.js</code></td><td>被动记录请求、响应头、响应体</td><td>单条响应体最多 20KB；最多缓存 100 条；二进制资源跳过 body 拉取</td></tr><tr><td>Token 统计</td><td><code>src/background/token-recorder.js</code>、<code>src/storage/token-store.js</code>、<code>src/side_panel/token-stats-panel.js</code></td><td>记录 prompt/completion/total token、上下文使用率、按模型与调用类型分布</td><td>部分模型不返回 total_tokens，用 prompt+completion 兜底</td></tr><tr><td>扩展端日志</td><td><code>src/shared/logger.js</code></td><td>DEBUG/INFO/WARN/ERROR 控制台输出</td><td>统一前缀 <code>[AIH]</code>，可通过级别控制</td></tr><tr><td>Agent 端日志</td><td><code>agent/src/logger.js</code></td><td>JSON Lines 审计日志、按日轮转、查询接口</td><td>支持 category、action、locale、stderr 输出</td></tr><tr><td>Side Panel 可见性</td><td><code>src/side_panel/panel-context.js</code></td><td>窗口 id、作用域、宿主 tab 快照</td><td>用于通知与跨通道 IPC 竞态下的可见性判断</td></tr></tbody></table><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/tools/debugger-tools.js#L1-L103" target="_blank" rel="noreferrer">src/background/tools/debugger-tools.js#L1-L103</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/tool-debugger.js#L1-L130" target="_blank" rel="noreferrer">src/background/tool-debugger.js#L1-L130</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/debugger/debugger-session.js#L1-L40" target="_blank" rel="noreferrer">src/background/debugger/debugger-session.js#L1-L40</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/token-recorder.js#L1-L36" target="_blank" rel="noreferrer">src/background/token-recorder.js#L1-L36</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/storage/token-store.js#L1-L45" target="_blank" rel="noreferrer">src/storage/token-store.js#L1-L45</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/side_panel/token-stats-panel.js#L1-L50" target="_blank" rel="noreferrer">src/side_panel/token-stats-panel.js#L1-L50</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/shared/logger.js#L1-L51" target="_blank" rel="noreferrer">src/shared/logger.js#L1-L51</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/logger.js#L1-L20" target="_blank" rel="noreferrer">agent/src/logger.js#L1-L20</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/side_panel/panel-context.js#L1-L18" target="_blank" rel="noreferrer">src/side_panel/panel-context.js#L1-L18</a></li></ul><h2 id="chrome-devtools-面板使用指南" tabindex="-1">Chrome DevTools 面板使用指南 <a class="header-anchor" href="#chrome-devtools-面板使用指南" aria-label="Permalink to &quot;Chrome DevTools 面板使用指南&quot;">​</a></h2><h3 id="console-面板调试" tabindex="-1">Console 面板调试 <a class="header-anchor" href="#console-面板调试" aria-label="Permalink to &quot;Console 面板调试&quot;">​</a></h3><ul><li>打开扩展后台页面：在 <code>chrome://extensions</code> 中找到 AI Helper，点击“Service Worker”或“Inspect views”。</li><li>查看扩展端日志：搜索 <code>[AIH]</code>，这是扩展端 logger 的统一前缀。</li><li>查看 Agent 端日志：启动 Agent 后，在终端中观察 stderr 输出的带时间戳、级别、分类标签的行。</li><li>过滤技巧： <ul><li>仅看错误：<code>console.error</code> 或筛选 <code>[AIH] ERROR</code>。</li><li>仅看调试信息：筛选 <code>[AIH] DEBUG</code>。</li><li>Agent 日志可按分类筛选，例如 <code>exec:</code>、<code>security:</code>、<code>auth:</code>。</li></ul></li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/shared/logger.js#L18-L40" target="_blank" rel="noreferrer">src/shared/logger.js#L18-L40</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/logger.js#L141-L152" target="_blank" rel="noreferrer">agent/src/logger.js#L141-L152</a></li></ul><h3 id="network-面板抓包" tabindex="-1">Network 面板抓包 <a class="header-anchor" href="#network-面板抓包" aria-label="Permalink to &quot;Network 面板抓包&quot;">​</a></h3><ul><li>常规抓包：在 DevTools Network 面板勾选 Preserve log，刷新页面或触发操作，观察 XHR/Fetch/WebSocket。</li><li>扩展内网访问限制：扩展自身发起的 fetch 不受 Chrome PNA 预检完全约束，因此内网拦截逻辑落在扩展侧；若发现请求未发出，应检查网络范围配置与安全判定。</li><li>WebSocket：关注 Upgrade 请求与后续 WS 帧；若流式输出异常，优先确认连接是否建立、是否被安全策略拒绝。</li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/test/unit/fetch-url-network-scope.unit.test.js#L1-L10" target="_blank" rel="noreferrer">test/unit/fetch-url-network-scope.unit.test.js#L1-L10</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/test/unit/network-scope.unit.test.js#L1-L12" target="_blank" rel="noreferrer">test/unit/network-scope.unit.test.js#L1-L12</a></li></ul><h3 id="performance-面板分析" tabindex="-1">Performance 面板分析 <a class="header-anchor" href="#performance-面板分析" aria-label="Permalink to &quot;Performance 面板分析&quot;">​</a></h3><ul><li>关注长任务：ReAct 推理循环、工具执行、截图生成、Markdown 渲染可能产生主线程阻塞。</li><li>关注内存峰值：大量 executionLog、DOM 属性膨胀、全量 DOM 扫描都可能造成增长。</li><li>结合 Token 统计：若某次调用 token 激增但无对应 UI 反馈，检查 executionLog 是否被截断或 API_COMPLETE 消息是否到达 side panel。</li></ul><p>[本节为通用性能分析方法，不直接分析具体代码文件]</p><h3 id="memory-面板检测" tabindex="-1">Memory 面板检测 <a class="header-anchor" href="#memory-面板检测" aria-label="Permalink to &quot;Memory 面板检测&quot;">​</a></h3><ul><li>重点观察： <ul><li>IndexedDB 中 token 记录数量增长。</li><li>side panel 中 executionLog 与 HTML 内容是否被存入 DOM dataset。</li><li>长时间使用后是否存在未释放的 debugger session。</li></ul></li><li>清理建议： <ul><li>清空 Token 统计：通过侧边栏 Token 统计面板的清空按钮。</li><li>关闭调试会话：确保 debug_page 最终调用 detach。</li><li>重启 Agent：修改 Agent 源码后必须重启进程。</li></ul></li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/side_panel/token-stats-panel.js#L136-L144" target="_blank" rel="noreferrer">src/side_panel/token-stats-panel.js#L136-L144</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/debugger/debugger-session.js#L301-L332" target="_blank" rel="noreferrer">src/background/debugger/debugger-session.js#L301-L332</a></li></ul><h2 id="扩展专用调试工具" tabindex="-1">扩展专用调试工具 <a class="header-anchor" href="#扩展专用调试工具" aria-label="Permalink to &quot;扩展专用调试工具&quot;">​</a></h2><h3 id="background-页面调试" tabindex="-1">Background 页面调试 <a class="header-anchor" href="#background-页面调试" aria-label="Permalink to &quot;Background 页面调试&quot;">​</a></h3><p>Background 是 MV3 Service Worker，存在生命周期硬约束：</p><ul><li>空闲会被终止，需要保活机制。</li><li>debugger-session 使用 <code>chrome.alarms</code> 在有活动会话时创建短周期 alarm，降低 SW 休眠导致会话丢失的概率。</li><li>若出现“会话不存在”“已脱离”类错误，优先检查是否触发了空闲自动脱离、用户取消调试、DevTools 抢占或标签页关闭。</li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/debugger/debugger-session.js#L101-L111" target="_blank" rel="noreferrer">src/background/debugger/debugger-session.js#L101-L111</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/debugger/debugger-session.js#L183-L196" target="_blank" rel="noreferrer">src/background/debugger/debugger-session.js#L183-L196</a></li></ul><h3 id="content-script-注入检测" tabindex="-1">Content Script 注入检测 <a class="header-anchor" href="#content-script-注入检测" aria-label="Permalink to &quot;Content Script 注入检测&quot;">​</a></h3><p>Content script 适合普通点击、输入、滚动和内容提取；当遇到以下情况时，应切换到 <code>debug_page</code>：</p><ul><li>原生事件（canvas、file input、忽略合成事件的控件）。</li><li>需要捕获 XHR/fetch 的请求体和响应体。</li><li>需要在页面最早时机执行 JS。</li><li>需要整页截图或设备/UA 模拟。</li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/tools/debugger-tools.js#L1-L7" target="_blank" rel="noreferrer">src/background/tools/debugger-tools.js#L1-L7</a></li></ul><h3 id="side-panel-界面调试" tabindex="-1">Side Panel 界面调试 <a class="header-anchor" href="#side-panel-界面调试" aria-label="Permalink to &quot;Side Panel 界面调试&quot;">​</a></h3><p>Side Panel 与 background 的消息传递是常见故障点：</p><ul><li>通知可见性判断依赖 panel-context 中的窗口 id、作用域、宿主 tab 快照。</li><li>若任务完成后通知行为异常，检查 side panel 是否可见、是否切换了 tab、background 是否冷启动。</li><li>Token 统计面板通过 IndexedDB 读取数据并渲染趋势图、分布图和全局统计。</li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/side_panel/panel-context.js#L1-L18" target="_blank" rel="noreferrer">src/side_panel/panel-context.js#L1-L18</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/side_panel/token-stats-panel.js#L204-L250" target="_blank" rel="noreferrer">src/side_panel/token-stats-panel.js#L204-L250</a></li></ul><h3 id="debug-page-工具流程" tabindex="-1">debug_page 工具流程 <a class="header-anchor" href="#debug-page-工具流程" aria-label="Permalink to &quot;debug_page 工具流程&quot;">​</a></h3><p><code>debug_page</code> 是扩展提供的强调试工具，其标准流程如下：</p><pre class="mermaid">sequenceDiagram
participant User as &quot;用户&quot;
participant Tool as &quot;debug_page 工具&quot;
participant Session as &quot;DebuggerSession&quot;
participant Tab as &quot;目标标签页&quot;
User-&gt;&gt;Tool : action=attach
Tool-&gt;&gt;Session : attach(tabId)
Session-&gt;&gt;Tab : chrome.debugger.attach
Session--&gt;&gt;Tool : 附着成功
Tool--&gt;&gt;User : 提示调试会话已开启
User-&gt;&gt;Tool : evaluate / input / network / screenshot / emulate
Tool-&gt;&gt;Session : cdp(...)
Session-&gt;&gt;Tab : CDP 命令
Tab--&gt;&gt;Session : 结果
Session--&gt;&gt;Tool : 返回结果
Tool--&gt;&gt;User : 工具结果
User-&gt;&gt;Tool : action=detach
Tool-&gt;&gt;Session : detach(tabId)
Session-&gt;&gt;Tab : 清除模拟覆盖并断开
Session--&gt;&gt;Tool : 脱离完成
Tool--&gt;&gt;User : 提示调试会话已关闭
</pre><p><strong>图表来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/tool-debugger.js#L531-L569" target="_blank" rel="noreferrer">src/background/tool-debugger.js#L531-L569</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/debugger/debugger-session.js#L221-L296" target="_blank" rel="noreferrer">src/background/debugger/debugger-session.js#L221-L296</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/debugger/debugger-session.js#L301-L332" target="_blank" rel="noreferrer">src/background/debugger/debugger-session.js#L301-L332</a></li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/tool-debugger.js#L132-L147" target="_blank" rel="noreferrer">src/background/tool-debugger.js#L132-L147</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/tool-debugger.js#L193-L233" target="_blank" rel="noreferrer">src/background/tool-debugger.js#L193-L233</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/debugger/debugger-session.js#L221-L296" target="_blank" rel="noreferrer">src/background/debugger/debugger-session.js#L221-L296</a></li></ul><h2 id="日志系统配置与使用" tabindex="-1">日志系统配置与使用 <a class="header-anchor" href="#日志系统配置与使用" aria-label="Permalink to &quot;日志系统配置与使用&quot;">​</a></h2><h3 id="扩展端日志" tabindex="-1">扩展端日志 <a class="header-anchor" href="#扩展端日志" aria-label="Permalink to &quot;扩展端日志&quot;">​</a></h3><p>扩展端 logger 提供四个级别：DEBUG、INFO、WARN、ERROR。默认级别为 DEBUG，所有级别都会输出到控制台，并以 <code>[AIH]</code> 作为统一前缀。</p><ul><li>设置日志级别：通过 <code>setLogLevel</code> 调整当前级别。</li><li>获取日志级别：通过 <code>getLogLevel</code> 查询。</li><li>输出方法：<code>debug</code>、<code>info</code>、<code>warn</code>、<code>error</code>。</li><li>使用建议： <ul><li>日常开发保留 DEBUG。</li><li>生产或性能敏感场景可提升到 INFO 或 WARN。</li><li>错误路径必须使用 error，便于在 Console 中快速定位。</li></ul></li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/shared/logger.js#L1-L51" target="_blank" rel="noreferrer">src/shared/logger.js#L1-L51</a></li></ul><h3 id="agent-端日志" tabindex="-1">Agent 端日志 <a class="header-anchor" href="#agent-端日志" aria-label="Permalink to &quot;Agent 端日志&quot;">​</a></h3><p>Agent 端日志模块采用 JSON Lines 格式，写入用户目录下的 <code>.ai-helper-agent/logs</code>，并按日轮转，保留最近 30 个日志文件，单个文件超过 10MB 会被清理。</p><ul><li>分类标签：auth、fs、exec、security、system。</li><li>级别标签：info、warn、error。</li><li>输出方式： <ul><li>前台模式可输出到 stderr。</li><li>始终追加写入当日日志文件。</li></ul></li><li>查询接口：支持按日期、分类、偏移和限制查询日志条目。</li><li>本地化：类别标签支持 zh/en。</li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/logger.js#L1-L12" target="_blank" rel="noreferrer">agent/src/logger.js#L1-L12</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/logger.js#L23-L49" target="_blank" rel="noreferrer">agent/src/logger.js#L23-L49</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/logger.js#L72-L123" target="_blank" rel="noreferrer">agent/src/logger.js#L72-L123</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/logger.js#L132-L172" target="_blank" rel="noreferrer">agent/src/logger.js#L132-L172</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/logger.js#L174-L230" target="_blank" rel="noreferrer">agent/src/logger.js#L174-L230</a></li></ul><h3 id="错误信息过滤" tabindex="-1">错误信息过滤 <a class="header-anchor" href="#错误信息过滤" aria-label="Permalink to &quot;错误信息过滤&quot;">​</a></h3><ul><li>扩展端：在 Console 中筛选 <code>[AIH] ERROR</code>。</li><li>Agent 端：在终端中筛选 <code>ERROR</code> 或按分类筛选 <code>security:</code>、<code>auth:</code>。</li><li>日志文件：使用 Agent 提供的日志查询接口，或按文件名 <code>agent-YYYY-MM-DD.log</code> 手动查看。</li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/shared/logger.js#L30-L40" target="_blank" rel="noreferrer">src/shared/logger.js#L30-L40</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/logger.js#L141-L162" target="_blank" rel="noreferrer">agent/src/logger.js#L141-L162</a></li></ul><h2 id="性能监控与-token-统计" tabindex="-1">性能监控与 Token 统计 <a class="header-anchor" href="#性能监控与-token-统计" aria-label="Permalink to &quot;性能监控与 Token 统计&quot;">​</a></h2><h3 id="token-使用统计采集" tabindex="-1">Token 使用统计采集 <a class="header-anchor" href="#token-使用统计采集" aria-label="Permalink to &quot;Token 使用统计采集&quot;">​</a></h3><p>Token 统计在 API 调用完成后由 background 触发记录：</p><ul><li>记录字段包括 sessionId、model、promptTokens、completionTokens、totalTokens、contextWindow、callType。</li><li>若模型未返回 total_tokens，则用 promptTokens + completionTokens 兜底。</li><li>记录失败不会中断主流程，仅记录 warn。</li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/token-recorder.js#L1-L36" target="_blank" rel="noreferrer">src/background/token-recorder.js#L1-L36</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/storage/token-store.js#L24-L45" target="_blank" rel="noreferrer">src/storage/token-store.js#L24-L45</a></li></ul><h3 id="token-存储与聚合" tabindex="-1">Token 存储与聚合 <a class="header-anchor" href="#token-存储与聚合" aria-label="Permalink to &quot;Token 存储与聚合&quot;">​</a></h3><p>Token 明细存储在 IndexedDB 的 <code>tokenStats</code> 表中，并提供多种聚合查询：</p><ul><li>会话维度：当前会话的总 token、调用次数、上下文使用率区间、最近 20 条记录。</li><li>全局维度：总会话数、总调用次数、总 token。</li><li>时间维度：最近 N 天每日聚合。</li><li>分布维度：按模型、按 callType 聚合。</li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/storage/token-store.js#L47-L98" target="_blank" rel="noreferrer">src/storage/token-store.js#L47-L98</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/storage/token-store.js#L104-L137" target="_blank" rel="noreferrer">src/storage/token-store.js#L104-L137</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/storage/token-store.js#L194-L225" target="_blank" rel="noreferrer">src/storage/token-store.js#L194-L225</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/storage/token-store.js#L283-L345" target="_blank" rel="noreferrer">src/storage/token-store.js#L283-L345</a></li></ul><h3 id="token-统计面板" tabindex="-1">Token 统计面板 <a class="header-anchor" href="#token-统计面板" aria-label="Permalink to &quot;Token 统计面板&quot;">​</a></h3><p>侧边栏 Token 统计面板提供三个 Tab：</p><ul><li>趋势：最近 20 次调用的 sparkline、上下文使用率区间条、Prompt/Completion 总量。</li><li>分布：Prompt/Completion 堆叠条、按模型分布、按调用类型分布。</li><li>全局：最近 30 天趋势 sparkline、总 token、总会话、总 API 调用。</li></ul><pre class="mermaid">flowchart TD
Start[&quot;打开 Token 统计面板&quot;] --&gt; Load[&quot;加载会话统计与全局统计&quot;]
Load --&gt; HasData{&quot;是否有数据&quot;}
HasData --&gt; |否| Empty[&quot;显示暂无数据&quot;]
HasData --&gt; |是| RenderTop[&quot;渲染顶部卡片&quot;]
RenderTop --&gt; RenderTabs[&quot;渲染趋势/分布/全局 Tab&quot;]
RenderTabs --&gt; Sparkline[&quot;渲染 sparkline 与条形图&quot;]
Sparkline --&gt; End[&quot;用户交互刷新或清空&quot;]
</pre><p><strong>图表来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/side_panel/token-stats-panel.js#L102-L144" target="_blank" rel="noreferrer">src/side_panel/token-stats-panel.js#L102-L144</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/side_panel/token-stats-panel.js#L204-L250" target="_blank" rel="noreferrer">src/side_panel/token-stats-panel.js#L204-L250</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/side_panel/token-stats-panel.js#L309-L338" target="_blank" rel="noreferrer">src/side_panel/token-stats-panel.js#L309-L338</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/side_panel/token-stats-panel.js#L468-L526" target="_blank" rel="noreferrer">src/side_panel/token-stats-panel.js#L468-L526</a></li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/side_panel/token-stats-panel.js#L1-L50" target="_blank" rel="noreferrer">src/side_panel/token-stats-panel.js#L1-L50</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/side_panel/token-stats-panel.js#L204-L250" target="_blank" rel="noreferrer">src/side_panel/token-stats-panel.js#L204-L250</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/side_panel/token-stats-panel.js#L383-L419" target="_blank" rel="noreferrer">src/side_panel/token-stats-panel.js#L383-L419</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/side_panel/token-stats-panel.js#L468-L526" target="_blank" rel="noreferrer">src/side_panel/token-stats-panel.js#L468-L526</a></li></ul><h3 id="执行时间与资源消耗分析" tabindex="-1">执行时间与资源消耗分析 <a class="header-anchor" href="#执行时间与资源消耗分析" aria-label="Permalink to &quot;执行时间与资源消耗分析&quot;">​</a></h3><ul><li>执行时间追踪：可在 ReAct 执行循环、工具执行器、API 调用前后添加计时逻辑，并结合 logger 输出耗时。</li><li>资源消耗分析： <ul><li>关注 executionLog 大小，避免超过 <code>chrome.runtime.sendMessage</code> 的 64MiB 限制。</li><li>关注截图尺寸与纹理上限，超长页面会被截断。</li><li>关注网络录制缓冲区，最多 100 条，单条响应体最多 20KB。</li></ul></li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/index.js#L1476-L1500" target="_blank" rel="noreferrer">src/background/index.js#L1476-L1500</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/tool-debugger.js#L117-L121" target="_blank" rel="noreferrer">src/background/tool-debugger.js#L117-L121</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/debugger/debugger-session.js#L18-L22" target="_blank" rel="noreferrer">src/background/debugger/debugger-session.js#L18-L22</a></li></ul><h2 id="网络抓包与-api-调试技巧" tabindex="-1">网络抓包与 API 调试技巧 <a class="header-anchor" href="#网络抓包与-api-调试技巧" aria-label="Permalink to &quot;网络抓包与 API 调试技巧&quot;">​</a></h2><h3 id="使用-debug-page-进行网络录制" tabindex="-1">使用 debug_page 进行网络录制 <a class="header-anchor" href="#使用-debug-page-进行网络录制" aria-label="Permalink to &quot;使用 debug_page 进行网络录制&quot;">​</a></h3><p><code>debug_page</code> 的 network 动作支持三种模式：</p><ul><li>start：开始录制，可选 filterUrl 过滤 URL。</li><li>collect：取回并清空缓冲的新请求。</li><li>stop：停止录制并返回剩余请求。</li></ul><pre class="mermaid">flowchart TD
A[&quot;调用 action=network, networkMode=start&quot;] --&gt; B[&quot;启用 Network.enable 并监听事件&quot;]
B --&gt; C{&quot;是否匹配 filterUrl&quot;}
C --&gt; |否| D[&quot;丢弃该请求&quot;]
C --&gt; |是| E[&quot;记录请求头、postData、resourceType&quot;]
E --&gt; F[&quot;Network.responseReceived 填充状态码、mimeType、响应头&quot;]
F --&gt; G[&quot;Network.loadingFinished 尝试拉取响应体&quot;]
G --&gt; H{&quot;是否可拉取且非二进制资源&quot;}
H --&gt; |是| I[&quot;解码 base64 或文本，截断至 20KB&quot;]
H --&gt; |否| J[&quot;跳过响应体&quot;]
I --&gt; K[&quot;collect/stop 返回序列化后的请求列表&quot;]
J --&gt; K
</pre><p><strong>图表来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/debugger/debugger-session.js#L113-L180" target="_blank" rel="noreferrer">src/background/debugger/debugger-session.js#L113-L180</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/debugger/debugger-session.js#L374-L406" target="_blank" rel="noreferrer">src/background/debugger/debugger-session.js#L374-L406</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/tool-debugger.js#L358-L387" target="_blank" rel="noreferrer">src/background/tool-debugger.js#L358-L387</a></li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/tools/debugger-tools.js#L69-L75" target="_blank" rel="noreferrer">src/background/tools/debugger-tools.js#L69-L75</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/tool-debugger.js#L358-L387" target="_blank" rel="noreferrer">src/background/tool-debugger.js#L358-L387</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/debugger/debugger-session.js#L113-L180" target="_blank" rel="noreferrer">src/background/debugger/debugger-session.js#L113-L180</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/test/unit/debugger-executor.unit.test.js#L530-L629" target="_blank" rel="noreferrer">test/unit/debugger-executor.unit.test.js#L530-L629</a></li></ul><h3 id="websocket-通信监控" tabindex="-1">WebSocket 通信监控 <a class="header-anchor" href="#websocket-通信监控" aria-label="Permalink to &quot;WebSocket 通信监控&quot;">​</a></h3><ul><li>在 DevTools Network 面板中筛选 WebSocket。</li><li>若连接失败，检查： <ul><li>扩展网络访问开关是否允许目标主机。</li><li>是否为 http/https 协议。</li><li>是否命中内网白名单规则。</li></ul></li><li>若连接成功但消息异常，结合 Agent 端日志与 side panel 执行日志定位。</li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/test/unit/fetch-url-network-scope.unit.test.js#L1-L10" target="_blank" rel="noreferrer">test/unit/fetch-url-network-scope.unit.test.js#L1-L10</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/test/unit/network-scope.unit.test.js#L1-L12" target="_blank" rel="noreferrer">test/unit/network-scope.unit.test.js#L1-L12</a></li></ul><h3 id="http-请求拦截与响应数据分析" tabindex="-1">HTTP 请求拦截与响应数据分析 <a class="header-anchor" href="#http-请求拦截与响应数据分析" aria-label="Permalink to &quot;HTTP 请求拦截与响应数据分析&quot;">​</a></h3><ul><li>使用 debug_page 的 network 录制捕获请求与响应体。</li><li>注意： <ul><li>二进制资源（图片、字体、媒体）不会拉取响应体。</li><li>响应体可能被截断。</li><li>多次 collect 具有 drain 语义，第二次 collect 通常为空。</li></ul></li><li>对 JSON 响应可直接粘贴到 JSON 查看器；对 Base64 响应注意解码失败分支。</li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/debugger/debugger-session.js#L159-L179" target="_blank" rel="noreferrer">src/background/debugger/debugger-session.js#L159-L179</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/tool-debugger.js#L370-L378" target="_blank" rel="noreferrer">src/background/tool-debugger.js#L370-L378</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/test/unit/debugger-executor.unit.test.js#L609-L629" target="_blank" rel="noreferrer">test/unit/debugger-executor.unit.test.js#L609-L629</a></li></ul><h2 id="常见调试场景与问题定位" tabindex="-1">常见调试场景与问题定位 <a class="header-anchor" href="#常见调试场景与问题定位" aria-label="Permalink to &quot;常见调试场景与问题定位&quot;">​</a></h2><h3 id="场景一-无法-attach-调试器" tabindex="-1">场景一：无法 attach 调试器 <a class="header-anchor" href="#场景一-无法-attach-调试器" aria-label="Permalink to &quot;场景一：无法 attach 调试器&quot;">​</a></h3><p><strong>现象</strong>：调用 debug_page attach 失败，或提示受限页面。<br><strong>原因</strong>：</p><ul><li>目标是 chrome://、扩展商店、PDF 阅读器等受限页面。</li><li>Service Worker 重启后出现“孤儿附着”，需要先强制 detach 再重试。</li><li>用户手动取消调试或 DevTools 抢占。</li></ul><p><strong>处理步骤</strong>：</p><ol><li>确认目标标签页是普通网页。</li><li>若报错包含“already attached”，让工具自动执行 detach + retry。</li><li>若仍失败，手动关闭目标标签页后重新 attach。</li></ol><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/debugger/debugger-session.js#L233-L296" target="_blank" rel="noreferrer">src/background/debugger/debugger-session.js#L233-L296</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/tool-debugger.js#L193-L203" target="_blank" rel="noreferrer">src/background/tool-debugger.js#L193-L203</a></li></ul><h3 id="场景二-evaluate-返回空或异常" tabindex="-1">场景二：evaluate 返回空或异常 <a class="header-anchor" href="#场景二-evaluate-返回空或异常" aria-label="Permalink to &quot;场景二：evaluate 返回空或异常&quot;">​</a></h3><p><strong>现象</strong>：evaluate 返回“无返回值”或抛出异常。<br><strong>原因</strong>：</p><ul><li>表达式无 return。</li><li>页面脚本抛错。</li><li>调试会话已脱离。</li></ul><p><strong>处理步骤</strong>：</p><ol><li>检查 expression 是否有效。</li><li>查看异常详情。</li><li>若提示会话不存在，先重新 attach。</li></ol><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/tool-debugger.js#L210-L233" target="_blank" rel="noreferrer">src/background/tool-debugger.js#L210-L233</a></li></ul><h3 id="场景三-input-点击无效" tabindex="-1">场景三：input 点击无效 <a class="header-anchor" href="#场景三-input-点击无效" aria-label="Permalink to &quot;场景三：input 点击无效&quot;">​</a></h3><p><strong>现象</strong>：click 没有触发目标元素。<br><strong>原因</strong>：</p><ul><li>selector 未找到元素。</li><li>元素存在但不可见（尺寸为 0）。</li><li>元素在视口外且未 scrollIntoView。</li><li>目标在 shadow root 中但未穿透。</li></ul><p><strong>处理步骤</strong>：</p><ol><li>先用 evaluate 验证 selector 是否能找到元素。</li><li>检查元素是否可见。</li><li>使用工具内部深查询逻辑，确保兼容 Web Components。</li></ol><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/tool-debugger.js#L235-L275" target="_blank" rel="noreferrer">src/background/tool-debugger.js#L235-L275</a></li></ul><h3 id="场景四-网络录制为空" tabindex="-1">场景四：网络录制为空 <a class="header-anchor" href="#场景四-网络录制为空" aria-label="Permalink to &quot;场景四：网络录制为空&quot;">​</a></h3><p><strong>现象</strong>：collect 返回“没有新的网络请求”。<br><strong>原因</strong>：</p><ul><li>未先调用 start。</li><li>页面未发生相关网络请求。</li><li>filterUrl 过滤掉了目标请求。</li><li>已 collect 过一次，缓冲区已被清空。</li></ul><p><strong>处理步骤</strong>：</p><ol><li>先调用 start。</li><li>触发页面操作。</li><li>再次 collect。</li><li>如需清空重录，先 stop 再 start。</li></ol><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/tool-debugger.js#L358-L387" target="_blank" rel="noreferrer">src/background/tool-debugger.js#L358-L387</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/test/unit/debugger-executor.unit.test.js#L609-L629" target="_blank" rel="noreferrer">test/unit/debugger-executor.unit.test.js#L609-L629</a></li></ul><h3 id="场景五-token-统计无数据" tabindex="-1">场景五：Token 统计无数据 <a class="header-anchor" href="#场景五-token-统计无数据" aria-label="Permalink to &quot;场景五：Token 统计无数据&quot;">​</a></h3><p><strong>现象</strong>：Token 统计面板显示暂无数据。<br><strong>原因</strong>：</p><ul><li>尚未发生 API 调用。</li><li>API 调用未返回 usage。</li><li>recordTokenUsage 静默失败。</li></ul><p><strong>处理步骤</strong>：</p><ol><li>检查 side panel 是否收到 API_COMPLETE。</li><li>检查 console 中是否有 TokenRecorder warn。</li><li>检查 IndexedDB 中 tokenStats 表是否有记录。</li></ol><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/token-recorder.js#L16-L36" target="_blank" rel="noreferrer">src/background/token-recorder.js#L16-L36</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/side_panel/token-stats-panel.js#L204-L250" target="_blank" rel="noreferrer">src/side_panel/token-stats-panel.js#L204-L250</a></li></ul><h3 id="场景六-side-panel-通知误判可见性" tabindex="-1">场景六：Side Panel 通知误判可见性 <a class="header-anchor" href="#场景六-side-panel-通知误判可见性" aria-label="Permalink to &quot;场景六：Side Panel 通知误判可见性&quot;">​</a></h3><p><strong>现象</strong>：任务完成后通知未弹出或重复弹出。<br><strong>原因</strong>：</p><ul><li>background 冷启动期间 panel-context 快照不一致。</li><li>side panel 作用域或宿主 tab 发生变化。</li><li>port 断开与 onDisconnect 存在跨通道 IPC 竞态。</li></ul><p><strong>处理步骤</strong>：</p><ol><li>检查 side panel 是否处于可见状态。</li><li>检查当前作用域是全局还是 tab 绑定。</li><li>检查 panel-context 是否正确上报窗口 id、作用域、宿主 tab。</li></ol><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/side_panel/panel-context.js#L1-L18" target="_blank" rel="noreferrer">src/side_panel/panel-context.js#L1-L18</a></li></ul><h2 id="依赖关系分析" tabindex="-1">依赖关系分析 <a class="header-anchor" href="#依赖关系分析" aria-label="Permalink to &quot;依赖关系分析&quot;">​</a></h2><pre class="mermaid">classDiagram
class DebuggerTools {
+DEBUGGER_TOOLS
+executeDebugPage(args, toolCallId)
}
class DebuggerSession {
+attach(tabId)
+detach(tabId, reason)
+cdp(tabId, method, params)
+startNetworkCapture(tabId, filter)
+collectNetwork(tabId)
+stopNetworkCapture(tabId)
}
class ToolDebugger {
+handleAttach()
+handleDetach()
+handleEvaluate()
+handleInput()
+handleNetwork()
+handleScreenshot()
+handleEmulate()
}
class TokenRecorder {
+recordTokenUsage(params)
}
class TokenStore {
+recordTokenCall(record)
+getSessionTokenSummary(sessionId)
+getOverallTokenSummary()
+getDailyTokenSummary(days)
+getTokenSummaryByModel()
+getTokenSummaryByCallType()
}
class TokenStatsPanel {
+initTokenStatsPanel(getActiveSessionId, showCustomConfirm)
}
DebuggerTools --&gt; ToolDebugger : &quot;定义工具参数&quot;
ToolDebugger --&gt; DebuggerSession : &quot;调用 CDP 与会话管理&quot;
TokenRecorder --&gt; TokenStore : &quot;持久化 token 记录&quot;
TokenStatsPanel --&gt; TokenStore : &quot;读取统计与分布&quot;
</pre><p><strong>图表来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/tools/debugger-tools.js#L8-L103" target="_blank" rel="noreferrer">src/background/tools/debugger-tools.js#L8-L103</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/tool-debugger.js#L531-L569" target="_blank" rel="noreferrer">src/background/tool-debugger.js#L531-L569</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/debugger/debugger-session.js#L221-L406" target="_blank" rel="noreferrer">src/background/debugger/debugger-session.js#L221-L406</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/token-recorder.js#L16-L36" target="_blank" rel="noreferrer">src/background/token-recorder.js#L16-L36</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/storage/token-store.js#L24-L345" target="_blank" rel="noreferrer">src/storage/token-store.js#L24-L345</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/side_panel/token-stats-panel.js#L102-L598" target="_blank" rel="noreferrer">src/side_panel/token-stats-panel.js#L102-L598</a></li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/tools/debugger-tools.js#L8-L103" target="_blank" rel="noreferrer">src/background/tools/debugger-tools.js#L8-L103</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/tool-debugger.js#L531-L569" target="_blank" rel="noreferrer">src/background/tool-debugger.js#L531-L569</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/debugger/debugger-session.js#L221-L406" target="_blank" rel="noreferrer">src/background/debugger/debugger-session.js#L221-L406</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/token-recorder.js#L16-L36" target="_blank" rel="noreferrer">src/background/token-recorder.js#L16-L36</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/storage/token-store.js#L24-L345" target="_blank" rel="noreferrer">src/storage/token-store.js#L24-L345</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/side_panel/token-stats-panel.js#L102-L598" target="_blank" rel="noreferrer">src/side_panel/token-stats-panel.js#L102-L598</a></li></ul><h2 id="故障排查清单" tabindex="-1">故障排查清单 <a class="header-anchor" href="#故障排查清单" aria-label="Permalink to &quot;故障排查清单&quot;">​</a></h2><table tabindex="0"><thead><tr><th>问题</th><th>检查项</th><th>处理方式</th></tr></thead><tbody><tr><td>attach 失败</td><td>是否受限页面、是否已有附着、是否 Service Worker 重启</td><td>切换到普通网页；等待自动修复或手动关闭标签页</td></tr><tr><td>evaluate 异常</td><td>表达式是否合法、是否返回 Promise、是否已 detach</td><td>修正表达式；重新 attach</td></tr><tr><td>input 无效</td><td>selector 是否存在、元素是否可见、是否在 shadow root</td><td>先用 evaluate 验证；使用工具内部深查询</td></tr><tr><td>network 录制为空</td><td>是否 start、是否触发请求、filterUrl 是否匹配</td><td>先 start，触发操作，再 collect</td></tr><tr><td>Token 统计为空</td><td>是否调用 API、usage 是否返回、recordTokenUsage 是否失败</td><td>检查 console warn 与 IndexedDB</td></tr><tr><td>通知异常</td><td>panel-context 快照、作用域、宿主 tab</td><td>检查 side panel 可见性与背景消息</td></tr><tr><td>Agent 日志缺失</td><td>是否前台模式、日志目录权限、是否重启进程</td><td>查看 stderr；确认日志目录；重启 Agent</td></tr></tbody></table><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/debugger/debugger-session.js#L233-L296" target="_blank" rel="noreferrer">src/background/debugger/debugger-session.js#L233-L296</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/tool-debugger.js#L210-L233" target="_blank" rel="noreferrer">src/background/tool-debugger.js#L210-L233</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/tool-debugger.js#L235-L275" target="_blank" rel="noreferrer">src/background/tool-debugger.js#L235-L275</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/tool-debugger.js#L358-L387" target="_blank" rel="noreferrer">src/background/tool-debugger.js#L358-L387</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/token-recorder.js#L16-L36" target="_blank" rel="noreferrer">src/background/token-recorder.js#L16-L36</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/side_panel/panel-context.js#L1-L18" target="_blank" rel="noreferrer">src/side_panel/panel-context.js#L1-L18</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/logger.js#L141-L162" target="_blank" rel="noreferrer">agent/src/logger.js#L141-L162</a></li></ul><h2 id="结论" tabindex="-1">结论 <a class="header-anchor" href="#结论" aria-label="Permalink to &quot;结论&quot;">​</a></h2><p>AI Helper 的调试体系围绕三条主线展开：</p><ul><li><strong>页面级调试</strong>：通过 <code>debug_page</code> 与 Chrome DevTools Protocol 实现 attach、evaluate、原生输入、截图和环境模拟。</li><li><strong>网络与 API 调试</strong>：通过 debugger-session 的网络录制捕获请求与响应体，并结合扩展侧网络范围判定与 Agent 端日志定位问题。</li><li><strong>性能与 Token 统计</strong>：通过 token-recorder 与 token-store 将 API 调用沉淀为 IndexedDB 记录，并在 side panel 中以趋势、分布、全局视图呈现。</li></ul><p>实际调试时，建议按以下顺序推进：</p><ol><li>先在 Console 中确认扩展端与 Agent 端日志是否正常。</li><li>使用 <code>debug_page</code> 完成页面级验证。</li><li>使用 network 录制抓取 HTTP/WebSocket 数据。</li><li>通过 Token 统计面板确认调用是否落地、token 是否合理。</li><li>若涉及 background 与 side panel 的交互，重点检查消息传递、可见性判断与 Service Worker 生命周期。</li></ol>`,172)])])}const u=r(o,[["render",i]]);export{d as __pageData,u as default};
